@dataclass(frozen=True)
class BotDecision:
    command: str
    reason: str
    secret: bool = False
    wait_seconds: float = 0.0


def _decision_payload(decision: BotDecision, stage: str) -> dict[str, Any]:
    metadata = classify_decision(decision.command, decision.reason, stage)
    return {
        "stage": stage,
        "reason": decision.reason,
        "command": "[REDACTED]" if decision.secret else decision.command,
        "redacted": decision.secret,
        "category": metadata.category,
        "safety_critical": metadata.safety_critical,
    }


def _connection_inactivity_timeout(policy: object, default: float) -> float:
    """Keep login silence and bounded logout cleanup on short deadlines."""
    if (
        bool(getattr(policy, "runtime_boundary_requested", False))
        and bool(getattr(policy, "midgaard_logout_pending", False))
    ):
        return min(default, _RUNTIME_BOUNDARY_ACK_TIMEOUT_SECONDS)
    if not bool(getattr(policy, "in_world", False)):
        return min(default, _LOGIN_INACTIVITY_TIMEOUT_SECONDS)
    return default


def _runtime_boundary_safe_healer(
    policy: object,
    state: CharacterState,
) -> bool:
    """Recognize a healer checkpoint where a stalled logout can stop safely."""
    return bool(
        getattr(policy, "runtime_boundary_requested", False)
        and getattr(policy, "midgaard_logout_pending", False)
        and state.room_vnum == "3054"
        and not state.dead
        and state.hp is not None
        and state.hp > 0
        and not _is_uncommandable(state)
        and not state.in_combat
        and not _enemy_records(state.enemies)
    )


def _runtime_boundary_room_arrival_acknowledges_command(
    policy: object,
    state: CharacterState,
    command_origin_room: str | None,
) -> bool:
    """Accept a safe healer arrival when DD4 omits the follow-up prompt."""
    return bool(
        command_origin_room
        and command_origin_room != "3054"
        and _runtime_boundary_safe_healer(policy, state)
    )


@dataclass(frozen=True)
class FieldHuntStop:
    route: tuple[str, ...]
    target: str | None = None
    where_target: str | None = None
    command_keyword: str | None = None
    actions: tuple[str, ...] = ()
    where_location_routes: tuple[tuple[str, tuple[str, ...]], ...] = ()
    where_relocation_routes: tuple[
        tuple[str, str, tuple[str, ...]], ...
    ] = ()
    # Restrict a route branch to locator labels that the live MUD actually
    # reported. This prevents a broad area label from selecting a narrower
    # source branch with different hazards.
    required_where_locations: tuple[str, ...] = ()
    maximum_where_relocations: int = 0
    where_area_file: str | None = None
    where_source_mobile_vnum: int | None = None
    where_neighbor_area_file: str | None = None
    where_neighbor_route_vnums: tuple[str, ...] = ()
    where_neighbor_move_cost: int = 0
    # A source-ranked split-reset preflight can require exact live counts by
    # room label before entering any of its target rooms.
    required_where_location_counts: tuple[tuple[str, int], ...] = ()
    abort_if_where_target_absent: bool = False
    # A source-vetted multi-room search may advance to its next stop after a
    # negative area-local ``where`` result. Ordinary locators remain fail
    # closed by default.
    continue_after_where_absent: bool = False
    abort_if_where_target_unlisted: bool = False
    abort_if_where_room_names: tuple[str, ...] = ()
    post_actions: tuple[str, ...] = ()
    required_items: tuple[str, ...] = ()
    # A direct action can acquire one exact source object from an opened
    # container when no room-line parser can identify it in advance.
    action_required_object_vnums: tuple[int, ...] = ()
    source_purchase: SourcePurchase | None = None
    # Some resource stops are complete only after the live affect confirms
    # that the acquired object was activated successfully.
    required_active_affects: tuple[str, ...] = ()
    allowed_bystanders: tuple[str, ...] = ()
    trivial_bystanders: tuple[str, ...] = ()
    rejected_consider_subjects: tuple[str, ...] = ()
    accepted_consider_fragments: tuple[str, ...] = ()
    required_consider_fragments: tuple[str, ...] = ()
    rejected_consider_fragments: tuple[str, ...] = ()
    minimum_health_ratio: float = _FIELD_CONTINUE_HEALTH_RATIO
    consider_only: bool = False
    exact_target: bool = False
    maximum_target_count: int = 1
    # A source-ranked plain sentinel reset may expose exactly two identical
    # instances. This opens pre-combat selection only; combat still requires
    # the ordinary singleton target limit.
    allow_source_sequential_duplicate_rotation: bool = False
    # A source-audited armed sentinel reset may expose exactly two identical
    # copies. Each copy must pass its own live consider and is fought alone.
    allow_source_duplicate_pair: bool = False
    minimum_target_count: int = 1
    inspect_equipped_carrier: bool = False
    require_isolated: bool = False
    # A source-ranked ordinary hunt may admit one exact, easy-considered,
    # unarmed bystander when the combined source budget fits. This is never
    # enabled for specials, required-loot routes, or protected probes. Coin
    # funding has a separate opt-in because its target may be below the XP
    # band while still requiring the same exact two-mobile safety proof.
    allow_source_bystander_encounter: bool = False
    allow_source_coin_bystander_encounter: bool = False
    crowd_retry_limit: int = 0
    crowd_retry_delay_seconds: float = 0.0
    allow_local_recovery: bool = False
    # Permit sleep only at an explicitly source-audited no-mob transit room;
    # ordinary field stops continue to recover at the Midgaard healer.
    allow_transit_recovery: bool = False
    # A route-only required-loot stop may traverse a source-audited room
    # without turning a lone bystander into an incidental combat objective.
    allow_opportunistic_attacks: bool = True
    # Some routes begin in a normal room and end at the audited waypoint. They
    # must travel before auditing the first room as a sleep location.
    allow_transit_recovery_at_start: bool = True
    # Source route planners can raise this above the normal 90% transit
    # recovery floor when the next leg needs nearly a full movement pool.
    transit_recovery_minimum_move: int = 0
    allow_below_band_for_required_loot: bool = False
    allow_below_band_for_source_coins: bool = False
    # Some required-loot routes have a source-audited, unavoidable gate mob.
    # Consider the exact live VNUM before allowing the gate fight; this is a
    # route safety exception, never progression evidence.
    route_gate_source_mobile_vnums: tuple[int, ...] = ()
    # A gate may be a fixed, below-band mobile that must be removed to reach a
    # locator-confirmed required-loot carrier.  This is opt-in because a low
    # consider normally means "do not spend a combat round".
    route_gate_allow_below_band: bool = False
    # Keep the exception tied to the source room where the gate was audited.
    route_gate_room_vnums: tuple[str, ...] = ()
    # Do not open a route gate merely because a stale room snapshot contains
    # its mobile; require the preceding bounded locator to confirm the carrier.
    route_gate_requires_locator_target: bool = False
    # Some source reset streams load several indistinguishable instances of
    # one otherwise safe sentinel.  This is a tightly audited exception to
    # the ordinary one-mobile isolation rule: fight one exact selector at a
    # time, never exceed the source reset capacity, and stop when the gate
    # item is acquired.
    route_gate_allow_same_source_duplicates: bool = False
    route_gate_same_source_instance_limit: int = 1
    route_gate_required_items: tuple[str, ...] = ()
    route_gate_requires_good_alignment: bool = False
    # Some source reset gates load multiple same-prototype mobiles that join
    # one another automatically.  Require an already verified sanctuary
    # reserve before opening that aggregate encounter.
    route_gate_requires_sanctuary: bool = False
    # A source-audited crowd of only the Forest poison swarms may be rechecked
    # once from the healer after the route has positively located the carrier.
    # This is separate from ordinary target-crowd retries and never authorizes
    # fighting the swarm as a group.
    route_gate_crowd_retry_limit: int = 0
    route_gate_crowd_retry_delay_seconds: float = 0.0
    # A required-loot endpoint may defer one source-audited, below-band hazard
    # until after the exact carrier is killed.  This never permits an engaged
    # hazard; the post-objective cleanup/recovery gates still own that case.
    deferred_required_loot_hazard_source_mobile_vnums: tuple[int, ...] = ()
    # Scan the immediate destination before entering a required-loot endpoint
    # that a wandering source mobile can make unsafe between packets.
    pre_entry_scan_room_vnums: tuple[str, ...] = ()
    pre_entry_scan_hazard_source_mobile_vnums: tuple[int, ...] = ()
    # A transient source-registered wanderer may leave the endpoint after a
    # short wait. This retry is opt-in, bounded, and never permits combat.
    pre_entry_scan_retry_limit: int = 0
    pre_entry_scan_retry_delay_seconds: float = 0.0
    route_gate_minimum_health_ratio: float = 0.90
    require_sanctuary: bool = False
    # Some source-ranked mage/witch routes rely on the source-defined familiar
    # as an opener. Never silently downgrade those stops to an unprotected
    # solo fight.
    require_familiar: bool = False
    # Some source plans require the familiar to open and then withdraw before
    # the player starts. This is an explicit XP-ownership rule, not a target
    # HP estimate or ordinary target-admission gate.
    familiar_withdraw_before_opener: bool = False
    familiar_staging_room_vnum: str | None = None
    source_familiar_finish_peak_round_damage: int | None = None
    minimum_combat_health_ratio: float = 0.0
    route_vnums: tuple[str, ...] = ()
    # A source-audited target may be visible on the official outbound route
    # before its own locator graph can reach the reset area. These rooms are
    # exact VNUMs, never room-label aliases, and only open interception.
    outbound_intercept_room_vnums: tuple[str, ...] = ()
    maximum_level_offset: int | None = None
    # A source-ranked plain target may use DD4's exact +2..+5 consider tier
    # after source route and the player's own-health checks pass.
    allow_lucky_consider: bool = False
    maximum_pursuit_steps: int = 1
    pursuit_room_vnums: tuple[str, ...] = ()
    selective_loot_keywords: tuple[str, ...] = ()
    abort_after_consider_rejection: bool = False
    abort_if_where_location_unknown: bool = False
    preserve_where_route_waypoints: bool = False
    source_mobile_vnum: int | None = None
    source_mobile_room_description: str | None = None
    source_reset_room_vnum: str | None = None
    # A wandering carrier may be inspected in a source-reachable room that
    # is not one of its reset rooms. Keep that locator destination explicit.
    source_search_room_vnum: str | None = None
    source_peak_round_damage: int | None = None
    source_critical_hit_damage: int | None = None
    # These source incoming bounds are used when a route requires sanctuary.
    # They preserve raw evidence; target HP is never used as a gate.
    protected_source_peak_round_damage: int | None = None
    protected_source_critical_hit_damage: int | None = None
    # Retained for source-plan and historical evidence metadata. Target HP is
    # not a current combat admission or withdrawal rule.
    require_damage_window_probe: bool = False
    damage_window_minimum_fraction: float = _FIELD_DAMAGE_WINDOW_MINIMUM_FRACTION
    source_target_hp_ceiling: int | None = None
    # Retained to identify old source-fuzz evidence paths. Fresh level,
    # identity, route, and live consider govern current admission.
    allow_unprotected_hp_fuzz_probe: bool = False
    # Retained for historical passive-target evidence; live target HP is not a
    # precombat veto.
    precombat_hp_probe: bool = False
    # Retained for source evidence and protection-route reporting. Sanctuary
    # addresses source hazards, not target HP admission.
    allow_protected_hp_fuzz_probe: bool = False
    # Retained for source evidence on armed targets. The first Char.Enemies
    # packet is observation data, not a target-HP gate.
    allow_protected_armed_hp_fuzz_probe: bool = False
    # Retained for source-special preparation and evidence. Source hazards and
    # live identity still govern room-entry actions.
    allow_protected_special_hp_fuzz_probe: bool = False
    # Retained for a source-audited aggressive endpoint. Route, identity,
    # level, consider, and the player's own health remain authoritative.
    allow_protected_aggressive_hp_fuzz_probe: bool = False
    # A narrow exception for an armed, non-aggressive economic special whose
    # source-verified required loot is the reason for entering the room.
    allow_source_economic_special_endpoint: bool = False
    # An exact unarmed Mirror Realm cleric carries the source-verified
    # Sanctuary staff. Its blindness/curse/dispel recovery path is the
    # Midgaard healer; this flag never generalizes to other cleric specials.
    allow_source_caerlin_special_endpoint: bool = False
    # Source-backed player output metadata supports planning and reports only;
    # target HP observations never become an admission veto.
    source_combat_action: str | None = None
    source_combat_min_damage: int | None = None
    source_combat_expected_damage: int | None = None
    source_combat_conservative_damage: int | None = None
    source_combat_max_actions: int | None = None
    source_combat_reference: str | None = None
    source_combat_opening_action: str | None = None
    source_combat_opening_min_damage: int | None = None
    source_combat_opening_expected_damage: int | None = None
    source_combat_opening_conservative_damage: int | None = None
    source_combat_opening_max_damage: int | None = None
    source_combat_opening_reference: str | None = None
    source_familiar_minimum_damage: int | None = None
    source_policy_id: str | None = None
    source_target_armed: bool | None = None
    # ``None`` means no source body-form proof is available.  A parsed zero
    # is meaningful evidence for an ordinary organic, non-huge target.
    source_target_body_form_flags: int | None = None
    source_loot_object_vnums: tuple[int, ...] = ()
    source_specials: tuple[str, ...] = ()
    # A source-proven low-level caster special can recover from blindness by
    # fleeing to a recallable neighbor and waiting beside Midgaard's healer.
    allow_healer_blindness_recovery: bool = False
    # A source-proven famous gas-breath target can apply nausea during combat;
    # the runner recalls immediately and waits for the healer's cure-poison
    # pulse before resuming the campaign.
    allow_healer_poison_recovery: bool = False
    # Source-ranked circuit legs can cross reboot-randomized room components.
    # Keep their source graph as a preference, but let the live GMCP graph
    # choose the actual exits for this stop.
    live_navigation_target: str | None = None
    live_navigation_entry_room: str | None = None
    live_navigation_start_index: int | None = None
    live_navigation_resume_index: int | None = None
    live_navigation_room_vnums: tuple[str, ...] = ()
    live_navigation_blocked_room_vnums: tuple[str, ...] = ()
    live_navigation_preferred_destinations: tuple[str, ...] = ()
    # A source-audited no-mob waypoint can still contain a fixed NPC that
    # DD4 proves cannot interact with this character. Keep those identities
    # explicit; every other live room target remains a hard stop.
    transit_allowed_bystanders: tuple[str, ...] = ()
    # An audited required-item gate may prefer the oldest exact duplicate
    # selector when its source reset order makes that a useful first attempt.
    # This is only ordering; live checks and item confirmation remain required.
    route_gate_prefer_oldest_target_id: bool = False
    route_economic_hunt_mobile_vnums: tuple[int, ...] = ()
    # Required loot may need a verified post-kill action before the stop can
    # return.  This is deliberately separate from simple equipment commands.
    verified_post_actions: tuple[HuntPostCommandAction, ...] = ()


def _protected_special_action_budget(
    state: CharacterState,
    stop: FieldHuntStop,
) -> int:
    """Return the bounded live action horizon for the exact gas contract."""
    try:
        source_max_actions = int(stop.source_combat_max_actions or 0)
    except (TypeError, ValueError):
        return 0
    if source_max_actions <= 0:
        return 0
    if not (
        stop.allow_protected_special_hp_fuzz_probe
        and stop.require_sanctuary
        and stop.allow_healer_poison_recovery
        and {
            str(special).casefold()
            for special in stop.source_specials
        }
        == {"spec_breath_gas"}
        and _has_named_affect(state.affects, "sanctuary")
    ):
        return source_max_actions
    # Gas breath is a fighting-only special whose damage and nausea are still
    # live-authoritative. Once sanctuary and the healer cure route are active,
    # permit the existing protected 36-action horizon, but never an unbounded
    # combat loop or a pre-sanctuary extension.
    return max(source_max_actions, _FIELD_PROTECTED_ZERO_DAMAGE_MAX_ACTIONS)


_FASTWALK_COMMAND_BUDGET_RESERVE = 128
_FASTWALK_STOP_COMMAND_OVERHEAD = 4


def _fastwalk_command_budget(
    route: Fastwalk,
    hunt_stops: Collection[FieldHuntStop],
) -> int:
    """Allow a finite hunt circuit to finish without removing its hard cap."""
    stop_work = sum(
        len(stop.route_vnums)
        + len(stop.route)
        + len(stop.actions)
        + len(stop.post_actions)
        + 3 * len(stop.verified_post_actions)
        + _FASTWALK_STOP_COMMAND_OVERHEAD
        for stop in hunt_stops
    )
    route_gate_retry_work = (
        2 * len(route.commands)
        if any(
            stop.route_gate_crowd_retry_limit > 0
            and stop.route_gate_crowd_retry_delay_seconds > 0
            for stop in hunt_stops
        )
        else 0
    )
    # Reserve the registered route once in each direction for a failed recall
    # and leave a bounded allowance for combat, loot, and healer cleanup.
    return (
        2 * len(route.commands)
        + route_gate_retry_work
        + stop_work
        + _FASTWALK_COMMAND_BUDGET_RESERVE
    )


class StarterPolicy:
    """Deterministic rules for creation and DD4's first training sequence."""

    def __init__(
        self,
        spec: CharacterSpec,
        password: str,
        *,
        objective_level: int = 2,
        arena_kill_limit: int | None = None,
        arena_respawn_wait: bool = True,
        ota_arena_research: bool = False,
        ota_arena_start_in_circuit: bool = False,
        ota_arena_allow_unprotected_fallback: bool = False,
        ota_arena_stage: str | None = None,
        ota_arena_target_index: int = 0,
        ota_arena_token_receipts: Collection[Mapping[str, Any]] = (),
        resupply_only: bool = False,
        return_home: bool = False,
        city_restock: bool = False,
        city_rearm: bool = False,
        city_rearm_pounding: bool = False,
        carried_weapon_comparison_request: Mapping[str, Any] | None = None,
        city_outfit: bool = False,
        combat_pouch_repack: bool = False,
        audit_combat_pouch: bool = False,
        use_sanctuary_potions: bool = True,
        guildmaster_research: bool = False,
        magic_shop_research: bool = False,
        magic_shop_buy_fly: bool = False,
        magic_shop_continue_to_fastwalk: bool = False,
        magic_shop_buy_see_invisible: bool = False,
        magic_shop_buy_water_breathing: bool = False,
        magic_shop_minimum_flight_duration: int | None = None,
        allow_bounded_city_shop_transit: bool = False,
        flight_borrowing: bool = False,
        prepare_learned_flight: bool = False,
        bank_excess_coins: bool = False,
        liquidate_loot: bool = False,
        extract_money_container: bool = False,
        money_container_keyword: str | None = None,
        emergency_provision_sale: bool = False,
        loot_sale_counts: Mapping[tuple[str, str], int] | None = None,
        loot_sale_history: list[Mapping[str, Any]] | None = None,
        known_sale_rejections: Collection[Mapping[str, Any]] = (),
        query_world_time: bool = False,
        world_time_probe: bool = False,
        deity_protection_probe: bool = False,
        recheck_city_shop_route: bool = False,
        recheck_field_city_route_rooms: tuple[str, ...] = (),
        recall_list_research: bool = False,
        fastwalk_route: Fastwalk | None = None,
        fastwalk_explore_direction: str | None = None,
        fastwalk_explore_depth: int = 1,
        fastwalk_attack_target: str | None = None,
        fastwalk_origin_actions: tuple[str, ...] = (),
        fastwalk_defer_provision_resupply: bool = False,
        urgent_food_acquisition: bool = False,
        fastwalk_required_free_weight: int = 0,
        fastwalk_xp_first_capacity_threshold: int = 0,
        fastwalk_required_move: int = 0,
        fastwalk_require_flight: bool = False,
        vault_stow_items: tuple[str, ...] = (),
        vault_claim_items: tuple[str, ...] = (),
        vault_wear_claimed_items: bool = False,
        vault_required_free_weight: int = 0,
        vault_only: bool = False,
        fastwalk_world_cache_items: tuple[str, ...] = (),
        fastwalk_world_cache_object_vnums: tuple[int, ...] = (),
        fastwalk_world_cache_skip_preflight: bool = False,
        fastwalk_train_before_departure: bool = False,
        required_practice_skill: str | None = None,
        required_practice_type: str = "physical",
        required_practice_target_percent: int = 60,
        required_practice_prerequisites: tuple[tuple[str, int], ...] = (),
        training_only: bool = False,
        training_travel: TrainingTravelPlan | None = None,
        fastwalk_require_invisibility: bool = False,
        fastwalk_hunt_stops: tuple[FieldHuntStop, ...] = (),
        fastwalk_hunt_start_index: int = 0,
        fastwalk_resume_scope: str | None = None,
        fastwalk_kill_limit: int | None = None,
        moria_research: bool = False,
        moria_depth: int = 0,
        gear_catalog: GearCatalog | None = None,
        source_mobile_targets: Mapping[str, tuple[str, ...]] | None = None,
        source_mobile_level_ranges: Mapping[str, tuple[int, int]] | None = None,
        source_mobile_level_ranges_by_vnum: Mapping[int, tuple[int, int]] | None = None,
        source_mobile_vnums_by_target_room: Mapping[
            str, Mapping[str, tuple[int, ...]]
        ]
        | None = None,
        source_mobile_special_profiles: Mapping[
            str,
            tuple[tuple[str, ...], ...],
        ]
        | None = None,
        source_mobile_special_profiles_by_vnum: Mapping[int, tuple[str, ...]]
        | None = None,
        source_mobile_non_assisting_by_target_room: Mapping[
            str, Mapping[str, bool]
        ]
        | None = None,
        source_mobile_can_join_by_vnum: Mapping[int, bool] | None = None,
        source_mobile_aggressive_by_vnum: Mapping[int, bool] | None = None,
        source_mobile_attack_programs_by_vnum: Mapping[int, bool] | None = None,
        source_world: WorldSource | None = None,
        practice_types_spent: frozenset[str] = frozenset(),
        deferred_practice_types: frozenset[str] = frozenset(),
        rejected_practice_skills: frozenset[str] = frozenset(),
        known_skills: Collection[str] = (),
        known_skill_levels: Mapping[str, int] | None = None,
        counterbalance_preparation_required: bool = False,
        counterbalanced_weapon_vnum: int | None = None,
        chained_weapon_vnum: int | None = None,
        title_configured: bool = False,
        description_configured: bool = False,
        selected_training_stat: str | None = None,
        maxed_stats: Collection[str] = (),
        verified_combat_pouch_potions: Mapping[str, int] | None = None,
        source_resource_reserve: Mapping[str, Any] | None = None,
        verified_source_resources: Mapping[str, Any] | None = None,
        fastwalk_skip_target_sightings: frozenset[tuple[str, str]] = frozenset(),
        source_ranked_consider_revalidation_policy_id: str | None = None,
        fastwalk_route_gate_attempted_selectors: Collection[str] = (),
        preserved_primary_weapon_vnum: int | None = None,
        gear_inventory_source_hints: Mapping[str, int] | None = None,
        subclass_selection: bool = False,
        subclass_change_keyword: str | None = None,
        field_city_prior_detour_evidence: Mapping[str, Any] | None = None,
        training_audit: Mapping[str, Any] | None = None,
        source_revision: str | None = None,
    ) -> None:
        if objective_level < 2:
            raise ValueError("objective_level must be at least 2")
        if arena_kill_limit is not None and arena_kill_limit < 1:
            raise ValueError("arena_kill_limit must be positive")
        if fastwalk_kill_limit is not None and fastwalk_kill_limit < 1:
            raise ValueError("fastwalk_kill_limit must be positive")
        if fastwalk_required_free_weight < 0:
            raise ValueError("fastwalk_required_free_weight must not be negative")
        if fastwalk_xp_first_capacity_threshold < 0:
            raise ValueError(
                "fastwalk_xp_first_capacity_threshold must not be negative"
            )
        if fastwalk_required_move < 0:
            raise ValueError("fastwalk_required_move must not be negative")
        if required_practice_type not in {"physical", "intellectual"}:
            raise ValueError(
                "required_practice_type must be physical or intellectual"
            )
        if not 1 <= int(required_practice_target_percent) <= 99:
            raise ValueError(
                "required_practice_target_percent must be between 1 and 99"
            )
        for prerequisite_skill, minimum_percent in required_practice_prerequisites:
            if not _normalize_skill_name(prerequisite_skill):
                raise ValueError("required practice prerequisites need a skill name")
            if not 1 <= int(minimum_percent) <= 99:
                raise ValueError(
                    "required practice prerequisite percentages must be between 1 and 99"
                )
        if moria_depth < 0:
            raise ValueError("moria_depth must not be negative")
        if subclass_selection and not spec.subclass:
            raise ValueError("subclass_selection requires a target subclass")
        if subclass_selection and not subclass_change_keyword:
            raise ValueError(
                "subclass_selection requires a source-backed change keyword"
            )
        if not 1 <= fastwalk_explore_depth <= 6:
            raise ValueError("fastwalk_explore_depth must be between 1 and 6")
        self._session_state_owner: LiveSessionState | None = None
        self._combat_session = CombatSessionController()
        self._travel_session = TravelSessionController()
        self._recovery_session = RecoverySessionController()
        self.spec = spec
        self.password = password
        self.source_revision = source_revision
        self.objective_level = objective_level
        self.arena_kill_limit = arena_kill_limit
        self.arena_respawn_wait = arena_respawn_wait
        self.ota_arena_research = bool(ota_arena_research)
        self.ota_arena_start_in_circuit = bool(ota_arena_start_in_circuit)
        self.ota_arena_allow_unprotected_fallback = bool(
            ota_arena_allow_unprotected_fallback
        )
        self.ota_arena_stage = (
            "target" if self.ota_arena_research and ota_arena_start_in_circuit
            else "entry" if self.ota_arena_research
            else None
        )
        if ota_arena_stage in {"entry", "target", "wizinvis", "exit", "return"}:
            self.ota_arena_stage = ota_arena_stage
        try:
            parsed_ota_arena_target_index = int(ota_arena_target_index)
        except (TypeError, ValueError):
            parsed_ota_arena_target_index = 0
        self.ota_arena_target_index = max(0, parsed_ota_arena_target_index)
        self.ota_arena_route_commands: tuple[str, ...] = ()
        self.ota_arena_route_index = 0
        self.ota_arena_pending_move: tuple[str, str | None] | None = None
        self.ota_arena_look_attempts = 0
        self.ota_arena_consider_issued = False
        self.ota_arena_where_pending = False
        self.ota_arena_where_observed = False
        self.ota_arena_where_buffer = ""
        self.ota_arena_where_locations: tuple[str, ...] = ()
        self.ota_arena_where_target_vnum: int | None = None
        self.ota_arena_where_retries = 0
        self.ota_arena_candidate_rooms: tuple[int, ...] = ()
        self.ota_arena_candidate_index = 0
        self.ota_arena_candidate_room_vnum: int | None = None
        self.ota_arena_pending_loot = False
        self.ota_arena_loot_attempts = 0
        self.ota_arena_current_target_vnum: int | None = None
        self.ota_arena_kill_records: list[dict[str, Any]] = []
        self.ota_arena_token_receipts: list[dict[str, Any]] = [
            dict(receipt)
            for receipt in ota_arena_token_receipts
            if isinstance(receipt, Mapping)
        ]
        self.ota_arena_forced_arrivals: list[dict[str, Any]] = []
        self.resupply_only = resupply_only
        self.return_home = return_home
        self.city_restock = city_restock
        self.city_rearm = city_rearm
        self.city_rearm_pounding = city_rearm_pounding
        self.carried_weapon_comparison = (
            WeaponComparison(dict(carried_weapon_comparison_request))
            if carried_weapon_comparison_request is not None else None
        )
        self.city_outfit = city_outfit
        self.combat_pouch_repack = combat_pouch_repack
        self.audit_combat_pouch = audit_combat_pouch
        self.use_sanctuary_potions = use_sanctuary_potions
        self.guildmaster_research = guildmaster_research
        self.magic_shop_research = magic_shop_research
        self.magic_shop_buy_fly = magic_shop_buy_fly
        self.magic_shop_continue_to_fastwalk = magic_shop_continue_to_fastwalk
        self.magic_shop_buy_see_invisible = magic_shop_buy_see_invisible
        self.magic_shop_buy_water_breathing = magic_shop_buy_water_breathing
        self.magic_shop_minimum_flight_duration = (
            max(1, int(magic_shop_minimum_flight_duration))
            if magic_shop_minimum_flight_duration is not None
            else None
        )
        self.allow_bounded_city_shop_transit = allow_bounded_city_shop_transit
        self.city_shop_transit = CityShopTransit()
        self.source_purchase_sessions: dict[int, SourcePurchaseSession] = {}
        self.field_city_preflight_active = False
        self.field_city_final_preflight_required = False
        self.field_city_final_preflight_started = False
        self.field_city_departure_stopped = False
        self.field_city_detour_attempted = (
            field_city_prior_detour_evidence is not None
        )
        self.field_city_detour_evidence = (
            dict(field_city_prior_detour_evidence)
            if field_city_prior_detour_evidence is not None
            else None
        )
        self.field_city_route_correction_attempted = False
        self.field_city_route_correction_evidence: dict[str, Any] | None = None
        self.flight_borrowing = flight_borrowing
        self.prepare_learned_flight = prepare_learned_flight
        self.learned_flight_preparation = FlightPreparation()
        self.learned_flight_affect_revision = 0
        self.route_visibility_affects_observed = False
        self.route_invisibility_revoked = False
