def forest_bear_claws_hunt_stops() -> tuple[FieldHuntStop, ...]:
    """Acquire the Forest kodiak's high-damage piercing claws.

    The area source gives the Kodiak a single reset room and ``ACT_STAY_AREA``;
    the latter confines it to Forest but does not keep it in that reset room.
    Keep the locator branch explicit so a live ``where`` result does not turn
    into blind movement through the poison-swarm rooms.
    """
    common = {
        "command_keyword": "bear",
        "required_items": ("pair of bears claws",),
        "exact_target": True,
        "allowed_bystanders": ("small boy",),
        "trivial_bystanders": ("mountain goblin",),
        "allow_below_band_for_required_loot": True,
        "minimum_combat_health_ratio": 0.25,
        "maximum_level_offset": 0,
        "source_mobile_vnum": 18001,
        "source_mobile_room_description": (
            "A giant Kodiak bear stands here chewing on a carcass."
        ),
        "source_policy_id": "forest-bear-claws-upgrade-10-29",
        "source_loot_object_vnums": (18000,),
    }
    stops = [
        FieldHuntStop(
            (),
            "kodiak bear",
            where_target="giant kodiak bear",
            actions=("where kodiak",),
            where_location_routes=(
                ("River bed", ("18028", "18029", "18030")),
            ),
            where_relocation_routes=(
                ("18026", "River bed", ("18025", "18023", "18027", "18028")),
                ("18028", "River bed", ("18029",)),
                ("18029", "River bed", ("18030",)),
            ),
            abort_if_where_target_absent=True,
            abort_if_where_room_names=("Medicine man's Lair",),
            source_reset_room_vnum="18026",
            **common,
        ),
        # Both source poison swarms are aggressive wanderers and can occupy
        # any of these same-name rooms.  A route gate may remove exactly one
        # isolated below-band swarm after the Kodiak locator has confirmed
        # this branch; a crowd or unknown mobile still aborts the route.
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18025", "18023", "18027", "18028"),
            required_where_locations=("River bed",),
            route_gate_source_mobile_vnums=(18002, 18003),
            route_gate_allow_below_band=True,
            route_gate_room_vnums=("18027", "18028"),
            route_gate_requires_locator_target=True,
            route_gate_crowd_retry_limit=1,
            route_gate_crowd_retry_delay_seconds=12.0,
            deferred_required_loot_hazard_source_mobile_vnums=(18002, 18003),
            **common,
        ),
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18028", "18029"),
            required_where_locations=("River bed",),
            route_gate_source_mobile_vnums=(18002, 18003),
            route_gate_allow_below_band=True,
            route_gate_room_vnums=("18029",),
            route_gate_requires_locator_target=True,
            route_gate_crowd_retry_limit=1,
            route_gate_crowd_retry_delay_seconds=12.0,
            deferred_required_loot_hazard_source_mobile_vnums=(18002, 18003),
            **common,
        ),
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18029", "18030"),
            required_where_locations=("River bed",),
            route_gate_source_mobile_vnums=(18002, 18003),
            route_gate_allow_below_band=True,
            route_gate_room_vnums=("18030",),
            route_gate_requires_locator_target=True,
            route_gate_crowd_retry_limit=1,
            route_gate_crowd_retry_delay_seconds=12.0,
            deferred_required_loot_hazard_source_mobile_vnums=(18002, 18003),
            **common,
        ),
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18025",),
            **common,
        ),
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18023",),
            **common,
        ),
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18024",),
            **common,
        ),
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=("18023", "18022"),
            **common,
        ),
    ]
    # The bear is stay-area rather than sentinel. Traverse every source-vetted
    # Forest room while excluding the poison-swarm branch, the medicine man's
    # lair, and exits into adjacent areas.
    safe_search = (
        "18021", "18020", "18019", "18018", "18017", "18013",
        "18012", "18011", "18010", "18009", "18008", "18007",
        "18006", "18005", "18004", "18003", "18002", "18001",
        "18000", "18001", "18002", "18003", "18004", "18031",
        "18032", "18033", "18054", "18033", "18032", "18031",
        "18004", "18034", "18035", "18036", "18037", "18038",
        "18039", "18040", "18041", "18043", "18044", "18045",
        "18046", "18045", "18044", "18043", "18041", "18040",
        "18039", "18038", "18037", "18036", "18035", "18034",
        "18004", "18005", "18006", "18007", "18008", "18009",
        "18010", "18011", "18012", "18013", "18014", "18015",
        "18016", "18048", "18016", "18047", "18049", "18050",
        "18051", "18052", "18053",
    )
    stops.extend(
        FieldHuntStop(
            (),
            "kodiak bear",
            route_vnums=(vnum,),
            **common,
        )
        for vnum in safe_search
    )
    return tuple(stops)


