@lru_cache(maxsize=2)
def _moria_sanctuary_locator_routes(
    source_route: tuple[str, ...],
) -> tuple[
    tuple[tuple[str, tuple[str, ...]], ...],
    tuple[tuple[str, str, tuple[str, ...]], ...],
]:
    """Build bounded locator sweeps for Moria's wandering potion carriers."""
    fallback_locations = (
        ("the tunnel", ("4064",)),
        (
            "the maze",
            ("4063", "4058", "4057", "4062", "4065", "4066"),
        ),
        ("the large cave", ("4069", "4071")),
    )
    fallback_relocations = (
        (
            "4064",
            "the maze",
            ("4063", "4058", "4057", "4062", "4065", "4066"),
        ),
        (
            "4064",
            "the large cave",
            ("4063", "4058", "4057", "4062", "4065", "4066", "4069", "4071"),
        ),
        (
            "4071",
            "the maze",
            ("4069", "4066", "4065", "4062", "4057", "4058", "4063"),
        ),
        ("4071", "the large cave", ("4069", "4071")),
    )
    source_path = (current_source_directory() / "moria.are")
    if not source_path.is_file():
        return fallback_locations, fallback_relocations
    try:
        area = parse_area_file(
            source_path,
            include_resets=False,
            include_entities=False,
            include_objects=False,
        )
    except (OSError, ValueError):
        return fallback_locations, fallback_relocations

    allowed = {str(room_vnum) for room_vnum in source_route}
    room_groups: dict[str, list[int]] = {}
    for room_vnum in source_route:
        room = area.rooms.get(int(room_vnum))
        if room is None:
            continue
        label = " ".join(room.name.casefold().split())
        if label:
            room_groups.setdefault(label, []).append(int(room_vnum))
    if not room_groups:
        return fallback_locations, fallback_relocations

    location_routes = tuple(
        (label, tuple(str(room_vnum) for room_vnum in destinations))
        for label, destinations in room_groups.items()
    )
    relocation_routes: list[tuple[str, str, tuple[str, ...]]] = []
    for origin in source_route:
        for label, destinations in room_groups.items():
            candidates: list[tuple[str, ...]] = []
            for destination in destinations:
                segment = _source_room_route(
                    area.rooms,
                    int(origin),
                    destination,
                    allowed_rooms={int(room_vnum) for room_vnum in allowed},
                )
                if segment is None or any(
                    str(room_vnum) not in allowed for room_vnum in segment
                ):
                    continue
                if segment:
                    candidates.append(tuple(str(room_vnum) for room_vnum in segment))
            if candidates:
                # Room labels are not unique in Moria. Relocate to one nearest
                # source-mapped room; the bounded live inspection must decide
                # what to do next rather than sweeping every matching room.
                relocation_routes.append((
                    origin,
                    label,
                    min(candidates, key=lambda route: (len(route), route)),
                ))
    if not relocation_routes:
        return fallback_locations, fallback_relocations
    return location_routes, tuple(relocation_routes)


def moria_sanctuary_potion_consider_stops(
    *,
    allow_source_route_gates: bool = False,
) -> tuple[FieldHuntStop, ...]:
    """Search the potion resets and nearby wander rooms without attacking."""
    source_route = (
        "4064",
        "4063",
        "4058",
        "4057",
        "4062",
        "4065",
        "4066",
        "4069",
        "4071",
        "4072",
        "4073",
    )
    where_location_routes, where_relocation_routes = (
        _moria_sanctuary_locator_routes(source_route)
    )

    def stop(
        route: tuple[str, ...],
        *,
        actions: tuple[str, ...] = (),
        route_gate_room_vnums: tuple[str, ...] = (),
    ) -> FieldHuntStop:
        route_gate_enabled = bool(
            allow_source_route_gates and route_gate_room_vnums
        )
        return FieldHuntStop(
            route,
            "large hobgoblin",
            where_target="large hobgoblin",
            where_source_mobile_vnum=4055,
            actions=actions,
            where_location_routes=where_location_routes,
            where_relocation_routes=where_relocation_routes,
            maximum_where_relocations=(8 if allow_source_route_gates else 1),
            abort_if_where_location_unknown=True,
            preserve_where_route_waypoints=True,
            consider_only=True,
            exact_target=True,
            route_gate_source_mobile_vnums=(
                (4053, 4056, 4050) if route_gate_enabled else ()
            ),
            route_gate_allow_below_band=route_gate_enabled,
            route_gate_room_vnums=(
                route_gate_room_vnums if route_gate_enabled else ()
            ),
            route_gate_requires_locator_target=route_gate_enabled,
        )

    return (
        stop(
            ("east", "north", "north", "east", "south", "down"),
            actions=("where hobgoblin",),
            route_gate_room_vnums=("4058", "4057", "4062"),
        ),
        stop(("west",)),
        stop(("north",)),
        stop(("west",)),
        stop(("south",)),
        stop(("east",)),
        stop(("east",)),
        stop(("east",)),
        stop(("west", "south")),
        stop(("west",)),
        stop(("south",)),
        stop(("east",)),
        stop(("east",)),
    )


def moria_sanctuary_potion_hunt_stops(
    *,
    safe_reset_only: bool = False,
    required_potion_count: int = 1,
    allow_source_route_gates: bool = False,
) -> tuple[FieldHuntStop, ...]:
    """Hunt the carrier, optionally restricting the search to room 4064."""
    if required_potion_count < 1:
        raise ValueError("required_potion_count must be positive")
    reset_room = moria_sanctuary_potion_consider_stops(
        allow_source_route_gates=(
            allow_source_route_gates and not safe_reset_only
        ),
    )[0]
    required_items = ("purple potion",) * required_potion_count
    if safe_reset_only and not allow_source_route_gates:
        # Below the deep-route level gate, following a wandering carrier into
        # Moria's maze can turn a recovery errand into an unrelated fight.
        # Inspect the source reset room and return if its carrier has moved.
        return (
            FieldHuntStop(
                reset_room.route,
                reset_room.target,
                required_items=(
                    *required_items,
                    *reset_room.required_items,
                ),
                allowed_bystanders=reset_room.allowed_bystanders,
                trivial_bystanders=reset_room.trivial_bystanders,
                minimum_health_ratio=_FIELD_HIGH_RISK_START_HEALTH_RATIO,
                exact_target=reset_room.exact_target,
                allow_below_band_for_required_loot=True,
                pre_entry_scan_room_vnums=("4064",),
                pre_entry_scan_hazard_source_mobile_vnums=(4051,),
                pre_entry_scan_retry_limit=1,
                pre_entry_scan_retry_delay_seconds=12.0,
                source_mobile_vnum=4055,
                source_mobile_room_description=(
                    "A large hobgoblin is here wondering if he should tear you apart."
                ),
                source_reset_room_vnum="4064",
                source_loot_object_vnums=(4050,),
            ),
        )
    return (
        FieldHuntStop(
            reset_room.route,
            reset_room.target,
            where_target=reset_room.where_target,
            where_source_mobile_vnum=reset_room.where_source_mobile_vnum,
            actions=reset_room.actions,
            where_location_routes=reset_room.where_location_routes,
            where_relocation_routes=reset_room.where_relocation_routes,
            maximum_where_relocations=8,
            abort_if_where_target_absent=True,
            abort_if_where_location_unknown=(
                reset_room.abort_if_where_location_unknown
            ),
            preserve_where_route_waypoints=reset_room.preserve_where_route_waypoints,
            required_items=(
                *required_items,
                *reset_room.required_items,
            ),
            allowed_bystanders=reset_room.allowed_bystanders,
            trivial_bystanders=reset_room.trivial_bystanders,
            minimum_health_ratio=_FIELD_HIGH_RISK_START_HEALTH_RATIO,
            exact_target=reset_room.exact_target,
            allow_below_band_for_required_loot=True,
            source_mobile_vnum=4055,
            source_mobile_room_description=(
                "A large hobgoblin is here wondering if he should tear you apart."
            ),
            source_reset_room_vnum="4064",
            source_loot_object_vnums=(4050,),
            route_gate_source_mobile_vnums=(
                *reset_room.route_gate_source_mobile_vnums,
            ),
            route_gate_allow_below_band=reset_room.route_gate_allow_below_band,
            route_gate_room_vnums=reset_room.route_gate_room_vnums,
            route_gate_requires_locator_target=(
                reset_room.route_gate_requires_locator_target
            ),
        ),
    )


